-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_laterality_clean
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_laterality_clean AS WITH norm AS (SELECT e.*, lower(main."trim"(regexp_replace(COALESCE(e.laterality, ''), '\s+', ' ', 'g'))) AS _lat, lower(main."trim"(regexp_replace(COALESCE(e.site, ''), '\s+', ' ', 'g'))) AS _site FROM main.canonical_path_malignant_events_v1 AS e), toks AS (SELECT n.*, CASE  WHEN (((n._lat = '') OR (n._lat IS NULL))) THEN (NULL) WHEN ((n._lat = 'bilateral')) THEN ('bilateral') WHEN ((((n._lat ~~ '%right%') OR (n._lat ~~ '%rigth%')) AND ((n._lat ~~ '%left%') OR (n._lat ~~ '%let lobe%')))) THEN ('bilateral') WHEN (((n._lat ~~ '%right%') OR (n._lat ~~ '%rigth%'))) THEN ('right') WHEN (((n._lat ~~ '%left%') OR (n._lat ~~ '%let lobe%') OR (n._lat ~~ '%lobectomy%'))) THEN ('left') WHEN (((n._lat ~~ '%isthmus%') OR (n._lat ~~ '%isthmsu%') OR (n._lat ~~ '%isthus%'))) THEN ('isthmus') WHEN (((n._lat ~~ '%neck%') OR (n._lat ~~ '%soft tissue%') OR (n._lat ~~ '%paratracheal%') OR (n._lat ~~ '%mediastinal%') OR (n._lat ~~ '%thyroglossal%') OR (n._lat ~~ '%pyramidal%') OR (n._lat ~~ '%suprasternal%') OR (n._lat ~~ '%thyroid bed%') OR (n._lat ~~ '%thyroid fossa%') OR (n._lat ~~ '%spine%') OR (n._lat ~~ '%retropharyngeal%') OR (n._lat ~~ '%anterior neck%') OR (n._lat ~~ '%pretracheal%') OR (n._lat ~~ '%midline%') OR (n._lat ~~ '%ectopic%') OR (n._lat ~~ '%remnant%') OR (n._lat ~~ '%mass%') OR (n._lat ~~ '%trachea%') OR (n._lat ~~ '%clavicular%') OR (n._lat ~~ '%residual%') OR (n._lat ~~ '%level %'))) THEN ('extra_thyroidal') ELSE 'nonlobular' END AS laterality_token, CASE  WHEN (((n._site = '') OR (n._site IS NULL))) THEN (NULL) WHEN ((n._site IN ('ll', 'l l'))) THEN ('left') WHEN ((n._site IN ('rl', 'r l'))) THEN ('right') WHEN ((((n._site ~~ '%right%') OR (n._site ~~ '%rigth%')) AND ((n._site ~~ '%left%') OR (n._site ~~ '%let lobe%')))) THEN ('bilateral') WHEN (((n._site ~~ '%right%') OR (n._site ~~ '%rigth%'))) THEN ('right') WHEN (((n._site ~~ '%left%') OR (n._site ~~ '%let lobe%') OR (n._site ~~ '%leeft%') OR (n._site ~~ 'lt lobe%'))) THEN ('left') WHEN (((n._site ~~ '%isthmus%') OR (n._site ~~ '%isthmsu%') OR (n._site ~~ '%isthus%'))) THEN ('isthmus') WHEN (((n._site ~~ '%neck%') OR (n._site ~~ '%soft tissue%') OR (n._site ~~ '%paratracheal%') OR (n._site ~~ '%mediastinal%') OR (n._site ~~ '%thyroglossal%') OR (n._site ~~ '%pyramidal%') OR (n._site ~~ '%suprasternal%') OR (n._site ~~ '%thyroid bed%') OR (n._site ~~ '%thyroid fossa%') OR (n._site ~~ '%remnant%') OR (n._site ~~ '%ectopic%') OR (n._site ~~ '%mass%') OR (n._site ~~ '%level %') OR (n._site ~~ '%retropharyngeal%') OR (n._site ~~ '%pretracheal%') OR (n._site ~~ '%midline%') OR (n._site ~~ '%spine%') OR (n._site ~~ '%clavicular%') OR (n._site ~~ '%trachea%') OR (n._site ~~ '%anterior%'))) THEN ('extra_thyroidal') ELSE 'nonlobular' END AS site_token FROM norm AS n)SELECT t.* EXCLUDE (_lat, _site), t.laterality AS laterality_raw, t.site AS site_raw, COALESCE(CASE  WHEN ((t.laterality_token IN ('left', 'right', 'bilateral', 'isthmus'))) THEN (t.laterality_token) WHEN ((t.site_token IN ('left', 'right', 'bilateral', 'isthmus'))) THEN (t.site_token) ELSE COALESCE(t.laterality_token, t.site_token) END, NULL) AS derived_laterality_final, (((t.laterality_token = 'left') AND (t.site_token = 'right')) OR ((t.laterality_token = 'right') AND (t.site_token = 'left'))) AS site_laterality_contradict_flag, ((t.laterality_token IN ('extra_thyroidal', 'nonlobular')) AND (t.site_token IS NOT NULL)) AS laterality_has_site_prose_flag FROM toks AS t;
